erpo a cuerpo con una antorcha encendida e impactas, causarás 1 de daño de fuego.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_de7c9fd07470e6fa$::jsonb and payload#>'{rules,definition,description}'=$verify_5a4b49e76e85ed57$[{"id":"official-table","rows":[["Antorcha","1 pc","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Antorcha. Una antorcha arde durante 1 hora y emite luz brillante en un radio de 6 m y luz tenue otros 6 m más allá. Si realizas un ataque cuerpo a cuerpo con una antorcha encendida e impactas, causarás 1 de daño de fuego.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$verify_5a4b49e76e85ed57$::jsonb and payload#>'{catalog,revision}'=$verify_4e07408562bedb8b$3$verify_4e07408562bedb8b$::jsonb and revision=2) union all select 'inventory:inv_7bd312122611060dea25827fb688d867' as failed where not exists(select 1 from public.campaign_state_fragments where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_9a776b0e541fb73ab6bceb871f78edce' and entity_id='inv_7bd312122611060dea25827fb688d867' and payload#>'{description}'=$verify_fb0110dc01b844c7$"Objeto · Precio base · Peso\nMochila · 2 po · 5 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_fb0110dc01b844c7$::jsonb and payload#>'{rules,definition,description}'=$verify_467c0a803342b9d2$[{"id":"official-table","rows":[["Mochila","2 po","5 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$verify_467c0a803342b9d2$::jsonb and payload#>'{catalog,revision}'=$verify_4e07408562bedb8b$3$verify_4e07408562bedb8b$::jsonb and revision=2) union all select 'inventory:inv_83a4152d5b72ec08b801e4bafd8e4b3f' as failed where not exists(select 1 from public.campaign_state_fragments where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_9a776b0e541fb73ab6bceb871f78edce' and entity_id='inv_83a4152d5b72ec08b801e4bafd8e4b3f' and payload#>'{description}'=$verify_5615c435e74bef0a$"Objeto · Precio base · Peso\nRaciones (1 día) · 5 pp · 2 lb\n\nRaciones. Las raciones contienen alimentos secos que resisten viajes largos, como cecina, fruta deshidratada, galletas y nueces.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_5615c435e74bef0a$::jsonb and payload#>'{features}'=$verify_6268396968fa5288$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Raciones. Las raciones contienen alimentos secos que resisten viajes largos, como cecina, fruta deshidratada, galletas y nueces.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_6268396968fa5288$::jsonb and payload#>'{rules,definition,description}'=$verify_f8f536bb79fb87b3$[{"id":"official-table","rows":[["Raciones (1 día)","5 pp","2 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Raciones. Las raciones contienen alimentos secos que resisten viajes largos, como cecina, fruta deshidratada, galletas y nueces.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$verify_f8f536bb79fb87b3$::jsonb and payload#>'{catalog,revision}'=$verify_4e07408562bedb8b$3$verify_4e07408562bedb8b$::jsonb and revision=2) union all select 'inventory:inv_a252bc1d36f23be404ff51cb7578a3d0' as failed where not exists(select 1 from public.campaign_state_fragments where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_9a776b0e541fb73ab6bceb871f78edce' and entity_id='inv_a252bc1d36f23be404ff51cb7578a3d0' and payload#>'{description}'=$verify_c15551ec8d633855$"Objeto · Precio base · Peso\nYesquero · 5 pp · 1 lb\n\nYesquero. Esta pequeña caja contiene un pedernal, un chispero y yescas (normalmente, tela seca untada en aceite) que se utilizan para encender un fuego. Utilizar el yesquero para prender una antorcha (o cualquier otra cosa altamente inflamable) requiere una acción. Encender cualquier otro tipo de fuego lleva 1 minuto.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_c15551ec8d633855$::jsonb and payload#>'{features}'=$verify_bd65b4d01e3d68ec$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Yesquero. Esta pequeña caja contiene un pedernal, un chispero y yescas (normalmente, tela seca untada en aceite) que se utilizan para encender un fuego. Utilizar el yesquero para prender una antorcha (o cualquier otra cosa altamente inflamable) requiere una acción. Encender cualquier otro tipo de fuego lleva 1 minuto.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_bd65b4d01e3d68ec$::jsonb and payload#>'{rules,definition,description}'=$verify_814298e44215c03b$[{"id":"official-table","rows":[["Yesquero","5 pp","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Yesquero. Esta pequeña caja contiene un pedernal, un chispero y yescas (normalmente, tela seca untada en aceite) que se utilizan para encender un fuego. Utilizar el yesquero para prender una antorcha (o cualquier otra cosa altamente inflamable) requiere una acción. Encender cualquier otro tipo de fuego lleva 1 minuto.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$verify_814298e44215c03b$::jsonb and payload#>'{catalog,revision}'=$verify_4e07408562bedb8b$3$verify_4e07408562bedb8b$::jsonb and revision=2) union all select 'inventory:inv_b567a4af472a9a818c0f490a85a9e23d' as failed where not exists(select 1 from public.campaign_state_fragments where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_9a776b0e541fb73ab6bceb871f78edce' and entity_id='inv_b567a4af472a9a818c0f490a85a9e23d' and payload#>'{description}'=$verify_a8c011a0d5114d92$"Objeto · Precio base · Peso\nJuego de dados · 1 pp · —\n\nJuegos. Esta categoría de objetos incluye varios tipos de juegos de azar, normalmente basados en dados o cartas (como la Apuesta de los Tres Dragones). En la tabla “Herramientas” aparecen algunos ejemplos comunes, pero existen otros. Si eres competente con un juego, puedes sumar tu bonificador por competencia a las pruebas de característica que hagas para jugar con él. Cada tipo de juego requiere su propia competencia independiente.\n\nLas herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_a8c011a0d5114d92$::jsonb and payload#>'{features}'=$verify_39ce10f378e10021$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Juegos. Esta categoría de objetos incluye varios tipos de juegos de azar, normalmente basados en dados o cartas (como la Apuesta de los Tres Dragones). En la tabla “Herramientas” aparecen algunos ejemplos comunes, pero existen otros. Si eres competente con un juego, puedes sumar tu bonificador por competencia a las pruebas de característica que hagas para jugar con él. Cada tipo de juego requiere su propia competencia independiente.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_39ce10f378e10021$::jsonb and payload#>'{rules,definition,description}'=$verify_3ec1f6f63d132ac1$[{"id":"official-table","rows":[["Juego de dados","1 pp","—"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Juegos. Esta categoría de objetos incluye varios tipos de juegos de azar, normalmente basados en dados o cartas (como la Apuesta de los Tres Dragones). En la tabla “Herramientas” aparecen algunos ejemplos comunes, pero existen otros. Si eres competente con un juego, puedes sumar tu bonificador por competencia a las pruebas de característica que hagas para jugar con él. Cada tipo de juego requiere su propia competencia independiente.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"tools-context-general","text":"Las herramientas te permiten realizar algo que de otra forma estaría fuera de tu alcance, como fabricar o reparar un objeto, falsificar un documento o forzar una cerradura. Tu raza, clase, trasfondo o dotes pueden hacerte competente con ciertas herramientas. La competencia con una herramienta te permite sumar tu bonificador por competencia a cualquier prueba de característica que hagas con dicha herramienta. Hay que tener en cuenta que el uso de herramientas no está atado a una única característica, ya que la competencia con ellas representa un conocimiento amplio sobre su empleo. De este modo, tu GM podría pedirte que realices una prueba de Destreza para tallar detalles delicados con unas herramientas de ebanista, mientras que esculpir algo a partir de una madera especialmente dura podría requerir una prueba de Fuerza.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-tools-context"],"provenance":"official-spanish"}]$verify_3ec1f6f63d132ac1$::jsonb and payload#>'{catalog,revision}'=$verify_4b227777d4dd1fc6$4$verify_4b227777d4dd1fc6$::jsonb and revision=3) union all select 'inventory:inv_dfa8ccdc4ac54f3f5a6ba411afd86e4a' as failed where not exists(select 1 from public.campaign_state_fragments where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_9a776b0e541fb73ab6bceb871f78edce' and entity_id='inv_dfa8ccdc4ac54f3f5a6ba411afd86e4a' and payload#>'{description}'=$verify_908dfa734a103f7e$"Objeto · Precio base · Peso\nPetate · 1 po · 7 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_908dfa734a103f7e$::jsonb and payload#>'{rules,definition,description}'=$verify_31b34ce008f3ab23$[{"id":"official-table","rows":[["Petate","1 po","7 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$verify_31b34ce008f3ab23$::jsonb and payload#>'{catalog,revision}'=$verify_4e07408562bedb8b$3$verify_4e07408562bedb8b$::jsonb and revision=2) union all select 'inventory:inv_3291b2c39524476b818bd6c416a3aba7' as failed where not exists(select 1 from public.campaign_state_fragments where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_b935626903ae074cc0314a11a812f47b' and entity_id='inv_3291b2c39524476b818bd6c416a3aba7' and payload#>'{description}'=$verify_13c2783a0f6c5ecf$"Objeto · Precio base · Peso\nAmuleto · 5 po · 1 lb\n\nSímbolo sagrado. Un símbolo sagrado es la representación de un dios o un panteón. Puede tratarse de un amuleto con la forma del dios, o del mismo símbolo, pero cuidadosamente grabado o esculpido en un escudo, o de una cajita que contenga un fragmento de una reliquia sagrada. El apéndice MJ-B, “Panteones histórico-fantásticos”, indica los símbolos que normalmente se asocian a los muchos dioses de multiverso. Un clérigo o un paladín puede utilizar un símbolo sagrado como canalizador mágico. Para ello, el lanzador deberá sostener el símbolo en la mano, llevarlo bien visible en alguna parte del cuerpo o sujetar un escudo que lo tenga grabado.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_13c2783a0f6c5ecf$::jsonb and payload#>'{features}'=$verify_20d6da3fc6e17a06$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Símbolo sagrado. Un símbolo sagrado es la representación de un dios o un panteón. Puede tratarse de un amuleto con la forma del dios, o del mismo símbolo, pero cuidadosamente grabado o esculpido en un escudo, o de una cajita que contenga un fragmento de una reliquia sagrada. El apéndice MJ-B, “Panteones histórico-fantásticos”, indica los símbolos que normalmente se asocian a los muchos dioses de multiverso. Un clérigo o un paladín puede utilizar un símbolo sagrado como canalizador mágico. Para ello, el lanzador deberá sostener el símbolo en la mano, llevarlo bien visible en alguna parte del cuerpo o sujetar un escudo que lo tenga grabado.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_20d6da3fc6e17a06$::jsonb and payload#>'{rules,definition,d